'use strict';
const $=s=>document.querySelector(s);
let lang='en', languageRole=null;
let state=null, view=new URLSearchParams(location.search).get('section')||'home', authMode='login', selectedCampaign=1, busy=false;
const params=new URLSearchParams(location.hash.slice(1));
let qrToken=params.get('checkin')||'',qrBooking=null,qrError='';if(qrToken)view='checkin';
const requestedPortal=location.pathname.startsWith('/inf/client/')?'client':new URLSearchParams(location.search).get('view');
const restaurantKey=location.pathname.startsWith('/inf/client/')?(location.pathname.split('/')[3]||new URLSearchParams(location.search).get('restaurant')||''):'';
const portal=['admin','client'].includes(requestedPortal)?requestedPortal:'influencer';
let invite=params.get('invite')||new URLSearchParams(location.search).get('invite')||'';
let setup=params.get('setup')||'';
if(invite||setup||portal==='influencer')authMode='register';
const T=(en,ko)=>lang==='ko'?ko:en;
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(c,k)=>esc(c[k+'_'+lang]||c[k+'_en']||'');
const money=n=>'₩'+Number(n||0).toLocaleString(lang==='ko'?'ko-KR':'en-US');
const label={reserved:['Reserved','예약 완료'],submitted:['In review','검수 중'],changes:['Changes requested','보완 요청'],approved:['Ready for payout','지급 대기'],paid:['Paid','지급 완료'],cancelled:['Cancelled','예약 취소']};
const badge=s=>`<span class="badge ${esc(s)}">${label[s]?T(...label[s]):esc(s)}</span>`;
const icons={home:'◫',book:'◷',campaigns:'▤',invites:'↗',creators:'◎',blacklist:'⊘',clients:'▦',checkin:'▣'};
const err={meal_checkin_required:['Show your QR at the restaurant. The restaurant must confirm meal provision before you submit your post.','식당 담당자가 QR로 방문·식사 제공을 확인한 후 게시물을 제출해 주세요.'],menu_required:['Enter the provided menu in both English and Korean before opening this campaign.','예약을 열기 전에 제공 메뉴를 영어와 한국어로 입력해 주세요.'],qr_invalid:['This QR is invalid or belongs to another restaurant.','유효하지 않은 QR이거나 다른 식당의 예약입니다.'],qr_cancelled:['This reservation was cancelled.','취소된 예약입니다.'],already_checked_in:['This reservation is already checked in.','이미 체크인 처리된 예약입니다.'],checkin_day:['Check-in is available on the scheduled visit date (KST) for an upcoming reservation.','예약된 방문 당일(한국 시간)의 예약 건만 체크인할 수 있습니다.'],tags_invalid:['Enter up to 30 hashtags, separated by spaces, such as #LABAB #Food.','해시태그는 #라밥 #맛집처럼 공백으로 구분해 최대 30개 입력하세요.'],tags_missing:['Your caption is missing required hashtags. Include every required tag.','캡션에 필수 해시태그가 누락되었습니다. 지정된 태그를 모두 넣어 주세요.'],caption_required:['Paste the caption used in your Instagram post.','인스타그램에 게시한 캡션을 붙여 넣어 주세요.'],guide_required:['Confirm that your actual post follows the guide.','실제 게시물에 가이드와 해시태그를 반영했는지 확인해 주세요.'],content_check_required:['Open the actual Instagram post and check the content requirements before approval.','실제 게시물의 가이드·해시태그 반영을 확인한 뒤 승인해 주세요.'],account_restricted:['New reservations are restricted for this account. Contact the operator for a review.','이 계정은 신규 예약이 제한되어 있습니다. 운영자에게 문의해 주세요.'],client_mismatch:['Use the account invited to this restaurant.','이 식당으로 초대받은 계정으로 로그인해 주세요.'],approval_required:['Your participation must be approved before booking.','운영자의 참여 승인 후 예약할 수 있습니다.'],login_required:['Please sign in to continue.','로그인 후 이용해 주세요.'],session_expired:['Your session expired. Refresh the page and try again.','세션이 만료됐습니다. 새로고침 후 다시 시도해 주세요.'],forbidden:['You do not have access to this item.','접근 권한이 없습니다.'],invalid_input:['Check the information and try again.','입력 내용을 확인해 주세요.'],signup_invalid:['Enter your name, a valid email and a password of at least 12 characters.','이름, 올바른 이메일, 12자 이상의 비밀번호를 입력해 주세요.'],instagram_invalid:['Enter your Instagram username without a URL.','주소 대신 인스타그램 아이디를 입력해 주세요.'],invite_invalid:['This invitation has expired or has already been used. Ask the operator for a new link.','만료되었거나 이미 사용한 초대입니다. 운영사에 새 링크를 요청해 주세요.'],email_used:['This email is already registered. Sign in to your account.','가입된 이메일입니다. 로그인해 주세요.'],login_invalid:['The email or password is incorrect.','이메일 또는 비밀번호를 확인해 주세요.'],rate_limit:['Too many attempts. Please try again in 15 minutes.','요청이 많습니다. 15분 뒤 다시 시도해 주세요.'],slot_unavailable:['This time is no longer available. Please refresh.','예약할 수 없는 시간입니다. 새로고침해 주세요.'],already_booked:['You already have a reservation for this campaign.','이미 참여 중인 캠페인입니다.'],slot_full:['This time is fully booked. Choose another time.','마감된 시간입니다. 다른 시간을 선택해 주세요.'],invalid_status:['This item has changed. Refresh the page to see its current status.','처리 상태가 변경되었습니다. 새로고침해 주세요.'],visit_first:['Submit your receipt after your scheduled visit.','예약된 방문 시간 이후에 제출할 수 있습니다.'],amount_invalid:['Enter the total amount on your receipt in KRW.','영수증의 실제 결제 금액을 원 단위로 입력해 주세요.'],post_invalid:['Enter an Instagram post or Reel URL starting with https://www.instagram.com/.','인스타그램 게시물 또는 릴스의 https 링크를 입력해 주세요.'],receipt_invalid:['Upload a JPG or PNG image, up to 8 MB.','8MB 이하 JPG 또는 PNG 이미지를 첨부해 주세요.'],receipt_required:['Please attach your receipt.','영수증을 첨부해 주세요.'],location_required:['Fill in the branch name and address in both languages before opening reservations.','예약을 열려면 지점명과 주소를 두 언어로 입력해 주세요.'],slot_invalid:['Check the dates, weekdays, time and capacity. The date range must be within 90 days.','날짜·요일·시간·인원을 확인해 주세요. 기간은 90일 이내로 설정해 주세요.'],slot_duplicate:['This time already exists.','이미 등록된 시간입니다.'],slot_has_bookings:['A booked time cannot be removed.','예약자가 있는 시간은 삭제할 수 없습니다.'],note_required:['Enter what needs to be corrected.','보완이 필요한 내용을 입력해 주세요.'],payment_ref_required:['Enter a transfer reference before marking this as paid.','실제 송금 후 거래 식별번호를 입력해 주세요.'],server_error:['We could not save this. Your input is still here; please try again.','저장하지 못했습니다. 입력 내용은 유지됩니다. 다시 시도해 주세요.'],network:['Unable to connect. Check your connection and try again.','연결할 수 없습니다. 네트워크를 확인하고 다시 시도해 주세요.']};
async function api(action,data){const opt={credentials:'same-origin'};if(data){opt.method='POST';opt.body=data instanceof FormData?data:new URLSearchParams(data);if(action!=='state')opt.body.set('csrf',state?.csrf||'')}let r;try{r=await fetch('/inf/api.php?action='+action+'&portal='+portal+(restaurantKey?'&restaurant='+encodeURIComponent(restaurantKey):'')+(params.get('demo')==='1'?'&demo=1':''),opt)}catch(e){throw new Error('network')}let j;try{j=await r.json()}catch(e){throw new Error('server_error')}if(!r.ok||j.error)throw new Error(j.error||'server_error');return j}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),5000)}
async function refresh(){state=await api('state',invite?{invite}:null);if(!state.campaigns.some(c=>Number(c.id)===Number(selectedCampaign)))selectedCampaign=state.campaigns[0]?.id||state.campaign?.id||1;if(qrToken&&view==='checkin'&&['admin','client'].includes(state.user?.role)){try{const result=await api('checkin_preview',{token:qrToken});qrBooking=result.booking;qrError=''}catch(e){qrBooking=null;qrError=T(...(err[e.message]||err.server_error))}}render()}
function button(text,attrs='',cls='primary'){return `<button class="${cls}" ${attrs}>${text}</button>`}
function input(name,title,value='',type='text',extra=''){return `<label class="field">${title}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function options(){return state.campaigns.map(c=>`<option value="${c.id}" ${Number(c.id)===Number(selectedCampaign)?'selected':''}>${field(c,'title')}${c.branch_en?' · '+field(c,'branch'):''}</option>`).join('')}
function picker(){return state.campaigns.length>1?`<label class="campaign-picker">${T('Campaign','캠페인')}<select id="campaign-picker">${options()}</select></label>`:''}
function current(){return state.campaigns.find(c=>Number(c.id)===Number(selectedCampaign))||state.campaign}
function screenRole(){return state?.user?.role||(setup?'admin':state?.invite?.role)||portal}
function syncRoleLanguage(){const r=screenRole();if(languageRole!==r){languageRole=r;lang=r==='influencer'?'en':'ko';try{const saved=localStorage.getItem('labab-language-'+r);if(saved==='en'||saved==='ko')lang=saved}catch(e){}}}
function roleName(){return screenRole()==='admin'?T('OPERATOR','운영자'):screenRole()==='client'?T('RESTAURANT CLIENT','식당 클라이언트'):T('INFLUENCER','인플루언서')}
function applyRoleTheme(){const role=screenRole();document.documentElement.dataset.role=role;document.title=(clientName()||'LABAB')+' · '+roleName();document.querySelector('link[rel="icon"]').href='/inf/favicon-'+role+'.svg';document.querySelector('meta[name="theme-color"]').content={admin:'#9a3412',client:'#163b79',influencer:'#116149'}[role]}
function clientName(){return state?.client_portal?.name||''}
let clientQuery='';
function clientRows(){const list=(state.clients||[]).filter(c=>c.name.toLowerCase().includes(clientQuery.toLowerCase()));return list.length?list.map(c=>{const camps=state.campaigns.filter(x=>Number(x.client_id)===Number(c.id));return `<article class="card"><div class="visit-head"><h2>${esc(c.name)}</h2><span class="badge ${Number(c.active_count)?'approved':'submitted'}">${Number(c.active_count)?T('Open campaigns','모집 중'):T('Preparing','준비 중')}</span></div><div class="visit-numbers"><span>${T('Campaigns','캠페인')}<strong>${c.campaign_count}</strong></span><span>${T('Client accounts','담당자 계정')}<strong>${c.account_count}</strong></span><span>${T('Reservations','참여 예약')}<strong>${c.booking_count}</strong></span></div><label class="field">${T('Dedicated client URL','전용 클라이언트 주소')}<input readonly value="${esc(c.url)}"></label><div class="button-row"><a class="secondary" href="${esc(c.url)}" target="_blank" rel="noopener">${T('Open client page ↗','클라이언트 페이지 열기 ↗')}</a>${button(T('Copy URL','주소 복사'),`type="button" data-portal-copy="${esc(c.url)}"`,'secondary')}${camps.length?button(T('Invite manager','담당자 초대'),`data-client-invite="${camps[0].id}"`,'secondary'):''}</div><h3>${T('Campaigns & branches','캠페인 및 지점')}</h3>${camps.map(x=>`<div class="slot-row"><div><strong>${field(x,'title')}</strong><small>${field(x,'branch')||T('Branch not configured','지점 미설정')}</small></div>${button(T('Manage','설정'),`data-manage-campaign="${x.id}"`,'secondary')}</div>`).join('')}</article>`}).join(''):`<div class="card empty">${T('No matching clients.','일치하는 클라이언트가 없습니다.')}</div>`}
function clientManagement(){return `${title(T('CLIENT MANAGEMENT','클라이언트 관리'),T('All restaurant clients','전체 클라이언트'),T('Manage each restaurant, its dedicated portal, campaigns and team invitations.','식당별 전용 페이지, 캠페인, 지점 설정과 담당자 초대를 관리하세요.'))}<div class="card"><label class="field">${T('Search restaurant name','식당명 검색')}<input id="client-search" type="search" value="${esc(clientQuery)}"></label><p>${T('Registered clients','등록된 클라이언트')}: <strong>${(state.clients||[]).length}</strong></p></div><div id="client-list">${clientRows()}</div><details class="card"><summary>${T('Add a new client','새 클라이언트 등록')}</summary><form data-api="new_campaign">${input('client_name',T('Restaurant name','식당 이름'),'','text','required maxlength="150"')}<div class="form-error"></div>${button(T('Create client','클라이언트 등록'),'type="submit"')}</form></details>`}
function clientPages(){return `<section class="card"><h3>${T('Dedicated restaurant portals','식당별 전용 클라이언트 페이지')}</h3><p class="muted">${T('Send each partner their own portal. New partners first register through a client invitation.','각 담당자에게 해당 식당의 전용 주소를 전달하세요. 최초 계정은 클라이언트 초대로 등록합니다.')}</p><div class="client-portals">${(state.clients||[]).map(c=>`<a class="client-portal-link" href="${esc(c.url)}"><strong>${esc(c.name)}</strong><span>${esc(c.url.replace('https://',''))}</span><b>→</b></a>`).join('')}</div></section>`}
function header(){const u=state?.user;return `<header class="topbar"><a class="brand" href="${esc(state?.client_portal?.url||'/inf/')}"><span class="brand-mark">L</span><strong>${esc(clientName()||'LABAB')}<span>${clientName()?T('RESTAURANT PORTAL','전용 클라이언트 페이지'):'CREATOR TABLE'}</span></strong></a><div class="top-actions"><div class="language" aria-label="${T('Language','언어')}"><button data-lang="en" class="${lang==='en'?'active':''}" aria-pressed="${lang==='en'}">EN</button><button data-lang="ko" class="${lang==='ko'?'active':''}" aria-pressed="${lang==='ko'}">한국어</button></div>${u?`<span class="account">${esc(u.name)}</span><button class="text-button" data-action="logout">${T('Log out','로그아웃')}</button>`:''}</div></header><div class="role-strip"><strong>${roleName()}</strong><span>${screenRole()==='admin'?T('Campaigns · reviews · payouts','캠페인 · 검수 · 정산 관리'):screenRole()==='client'?T('Your restaurant · schedules · visits','우리 매장 · 일정 · 방문 관리'):T('Book · share · earn','방문 예약 · 콘텐츠 제출 · 리워드')}</span></div>`}
const isProvided=c=>c.meal_mode==='provided';
const mealModeName=c=>isProvided(c)?T('QR meal provided','QR 식사 제공형'):T('Pay first · reimbursement','선결제·환급형');
function mealTerms(c){if(state?.user?.role==='client')return `<div class="notice"><strong>${mealModeName(c)}</strong><p>${isProvided(c)?(c.offer_type==='menu'?T('Provided menu: ','제공 메뉴: ')+field(c,'menu'):T('Provide the meal according to the arrangement with the operator.','운영사와 협의한 조건에 따라 식사를 제공해 주세요.')):T('The creator pays for the meal directly.','인플루언서가 매장에서 직접 결제하는 방식입니다.')}</p></div>`;return `<div class="notice"><strong>${mealModeName(c)}</strong><p>${isProvided(c)?(c.offer_type==='menu'?T('Provided menu: ','제공 메뉴: ')+field(c,'menu'):T('Meals provided up to ','식사 제공 한도 ')+money(c.cap)):T('Pay for your meal and upload the receipt. Meal reimbursement is capped at ','직접 결제 후 영수증을 제출하세요. 식비 환급 한도 ')+money(c.cap)}</p><small>${isProvided(c)?T('Show your QR before ordering. No receipt is needed. Only the extra creator reward is paid after content approval; meal costs are not reimbursed.','주문 전에 QR을 보여 주세요. 영수증은 필요하지 않으며, 게시물 검수 후 추가 리워드만 지급합니다. 식비는 별도로 환급하지 않습니다.'):T('Keep your receipt and submit the campaign content after your visit.','영수증을 보관하고 방문 후 캠페인 게시물을 제출하세요.')}</small></div>`}
function rewardCard(c){if(isProvided(c))return `<div class="reward-card"><span class="eyebrow">${T('YOUR CAMPAIGN BENEFITS','캠페인 참여 혜택')}</span><div class="benefit"><span>${T('Meal provided by restaurant','식당에서 식사 제공')}<small>${c.offer_type==='menu'?field(c,'menu'):T('Within the campaign limit','캠페인 한도 내 제공')}</small></span><strong>${c.offer_type==='menu'?T('Set menu','지정 메뉴'):money(c.cap)}</strong></div><div class="benefit"><span>${T('Extra creator reward','추가 리워드')}<small>${T('After content approval','게시물 검수 후')}</small></span><strong>${money(c.reward)}</strong></div><div class="total"><span>${T('Cash payout','현금 지급액')}</span><strong>${money(c.reward)}</strong></div></div>`;return `<div class="reward-card"><span class="eyebrow">${T('YOUR CAMPAIGN BENEFITS','캠페인 참여 혜택')}</span><div class="benefit"><span>${T('Meal reimbursement','식비 환급')}<small>${T('Up to the amount on your receipt','영수증 실제 결제액 기준')}</small></span><strong>${money(c.cap)}<small>${T('maximum','한도')}</small></strong></div><div class="benefit"><span>${T('Creator reward','추가 리워드')}<small>${T('After content approval','게시물 검수 승인 후')}</small></span><strong>+ ${money(c.reward)}</strong></div><div class="total"><span>${T('Earn up to','최대 총 지급액')}</span><strong>${money(Number(c.cap)+Number(c.reward))}</strong></div></div>`}
function campaignImage(c){return ({1:'/inf/images/campaign-labab.jpg',2:'/inf/images/campaign-kalguksu.jpg',3:'/inf/images/campaign-chicken.jpg',4:'/inf/images/campaign-chinese.jpg',5:'/inf/images/campaign-korean.jpg',6:'/inf/images/campaign-cafe.jpg'})[Number(c.client_id)]||'/inf/images/campaign-korean.jpg'}
function campaignCards(){return `<div class="campaign-grid">${state.campaigns.map((c,i)=>`<article class="campaign-tile"><img class="campaign-image" src="${campaignImage(c)}" alt="${esc(field(c,'title'))}" loading="lazy"><div class="tile-top"><span class="tile-number">${String(i+1).padStart(2,'0')}</span><span class="badge ${Number(c.active)?'approved':''}">${Number(c.active)?T('View visit times','예약 일정 확인'):T('Coming soon','오픈 준비 중')}</span></div><h2>${field(c,'title')}</h2><p>${field(c,'branch')||T('Branch details coming soon','지점 정보 준비 중')}</p><p class="meal-mode">${mealModeName(c)}</p><div class="tile-reward"><span>${isProvided(c)?(c.offer_type==='menu'?T('Provided menu','지정 메뉴 제공'):T('Meal provided up to','식사 제공 한도')):T('Meal reimbursement up to','식비 환급 최대')} <b>${isProvided(c)&&c.offer_type==='menu'?T('See details','상세 확인'):money(c.cap)}</b></span><span>${T('Extra reward','추가 리워드')} <b>${money(c.reward)}</b></span></div>${button(T('View campaign →','캠페인 자세히 →'),`data-campaign="${c.id}"`,'secondary full')}</article>`).join('')}</div>`}
function approvalNotice(){const u=state.user;if(!u||u.role!=='influencer')return '';if(Number(u.is_blacklisted))return `<div class="approval-notice pending"><strong>${T('New reservations are restricted','신규 예약이 제한되었습니다.')}</strong><span>${T('Contact the operator for a review. Your existing visits and submissions remain accessible.','운영자에게 문의해 주세요. 기존 예약 확인 및 자료 제출은 계속 이용할 수 있습니다.')}</span></div>`;if(u.approval_status==='approved')return `<div class="approval-notice approved"><strong>${T('You’re approved to participate.','참여 승인이 완료되었습니다.')}</strong><span>${T('Choose an open campaign and reserve your visit.','예약이 열린 캠페인을 선택해 방문을 예약하세요.')}</span></div>`;return `<div class="approval-notice pending"><strong>${u.approval_status==='rejected'?T('Participation is not approved','참여 미승인'):T('Participation approval pending','참여 승인 대기')}</strong><span>${T('You can explore all campaigns. Reservations become available after operator approval.','모든 캠페인을 둘러볼 수 있습니다. 운영자의 참여 승인 후 예약할 수 있습니다.')}</span>${u.approval_note?`<p>${esc(u.approval_note)}</p>`:''}</div>`}
function catalogHome(){return `${title(T('EXPLORE CAMPAIGNS','캠페인 둘러보기'),T('Find your next food story.','어떤 맛을 만나볼까요?'),T('Discover restaurants, check the requirements and choose your next visit.','식당별 참여 조건을 살펴보고 원하는 캠페인을 선택하세요.'))}${approvalNotice()}${campaignCards()}`}
function guest(){const reg=authMode==='register';const c=current();return `<main class="public-catalog"><section class="public-intro"><span class="eyebrow orange">${T('CREATOR CAMPAIGNS','인플루언서 캠페인')}</span><h1>${T('Your next food story<br>starts here.','맛있는 경험,<br>여기서 시작하세요.')}</h1><p>${T('Sign up, get approved and explore restaurant campaigns.','회원가입 후 참여 승인을 받고 다양한 식당 캠페인에 참여하세요.')}</p><div class="onboarding-steps"><span>01 ${T('Sign up','회원가입')}</span><span>02 ${T('Get approved','참여 승인')}</span><span>03 ${T('Book & share','방문 예약·게시')}</span></div><a class="link" href="#creator-account">${T('Create an account or sign in ↓','회원가입 / 로그인 ↓')}</a></section><div class="public-columns"><section class="public-campaigns"><div class="section-head"><h3>${T('Restaurant campaigns','식당 캠페인')}</h3><span class="muted">${state.campaigns.length} ${T('campaigns','개 캠페인')}</span></div>${campaignCards()}${view==='detail'?`<section class="card public-detail"><span class="eyebrow">${T('CAMPAIGN DETAILS','캠페인 상세')}</span><h2>${field(c,'title')}</h2><p>${field(c,'branch')||T('Branch to be announced','지점 준비 중')}</p><p>${field(c,'address')||T('Address to be announced','주소 준비 중')}</p><p class="preline">${field(c,'guide')}</p>${hashtagPanel(c)}<p class="notice">${T('Create an account and get participation approval before booking.','가입하고 운영자의 참여 승인을 받은 뒤 예약할 수 있습니다.')}</p></section>`:''}</section><section class="auth-panel" id="creator-account"><div class="mini-logo">${T('INFLUENCER ACCOUNT','인플루언서 계정')}</div><div class="auth-tabs"><button type="button" data-mode="register" class="${reg?'selected':''}">${T('Sign up','회원가입')}</button><button type="button" data-mode="login" class="${!reg?'selected':''}">${T('Sign in','로그인')}</button></div><h2>${reg?T('Join the table.','함께할 준비 되셨나요?'):T('Welcome back.','다시 만나 반가워요.')}</h2><p>${reg?T('No invitation needed. Our team reviews your Instagram profile before enabling reservations.','초대 링크 없이 가입할 수 있습니다. 운영사가 인스타그램 계정을 확인한 후 예약을 승인합니다.'):T('Sign in to view your campaigns and rewards.','로그인하고 캠페인과 리워드를 확인하세요.')}</p>${invite&&!state.invite?`<div class="notice warn">${T(...err.invite_invalid)}</div>`:''}<form data-api="${reg?'register':'login'}"><input type="hidden" name="invite" value="${esc(invite)}"><input type="hidden" name="setup" value="">${reg?input('name',T('Full name','이름'),'','text','required autocomplete="name" maxlength="100"'):''}${input('email',reg?T('Email address','이메일'):T('Email or username','이메일 또는 아이디'),'',reg?'email':'text',`required autocomplete="${reg?'email':'username'}" maxlength="180"`)}${input('password',T('Password','비밀번호'),'','password',`required autocomplete="${reg?'new-password':'current-password'}" ${reg?'minlength="12"':''} maxlength="128"`)}${reg?input('instagram',T('Instagram username','인스타그램 아이디'),'','text','required placeholder="@yourname" maxlength="30"'):''}${reg?`<p class="form-help">${T('Password: at least 12 characters. Registration does not verify ownership of your email or Instagram account.','비밀번호는 12자 이상입니다. 가입만으로 이메일 또는 인스타그램 계정 소유권이 인증되지는 않습니다.')}</p><label class="check"><input type="checkbox" required>${T('I agree to use my profile and submissions for campaign operations. My name, Instagram profile, reservation and post are shared with the restaurant I book.','캠페인 운영을 위한 프로필·제출 자료 이용에 동의합니다. 예약한 식당에는 이름·인스타그램 계정·예약·게시물이 공유됩니다.')}</label>`:''}<div class="form-error"></div>${button(reg?T('Create account →','가입하기 →'):T('Sign in →','로그인 →'),'type="submit"','primary full')}</form><p class="form-help account-help">${reg?T('You can browse every campaign while your participation approval is pending.','참여 승인 대기 중에도 모든 캠페인을 볼 수 있습니다.'):T('Demo access: use the demo ID provided by the operator.','체험은 안내받은 체험용 아이디로 로그인하세요.')}</p></section></div></main>`}
let creatorQuery='',creatorFilter='all';
const restrictionReason=r=>({no_show:T('No-show','노쇼'),late_cancel:T('Late cancellation','직전 취소'),content_issue:T('Content requirements not met','게시물 조건 미이행'),other:T('Other','기타'),release:T('Restriction lifted','등록 해제')}[r]||r);
function creatorList(){const q=creatorQuery.trim().toLowerCase(),filter=view==='blacklist'?'blocked':creatorFilter;const list=(state.creators||[]).filter(u=>(!q||[u.name,u.email,u.instagram].some(x=>String(x).toLowerCase().includes(q)))&&(filter==='all'||filter==='blocked'&&Number(u.is_blacklisted)||filter==='pending'&&u.approval_status==='pending'||filter==='approved'&&u.approval_status==='approved'&&!Number(u.is_blacklisted)));return list.length?list.map(u=>{const blocked=!!Number(u.is_blacklisted),events=(state.blacklist_events||[]).filter(e=>Number(e.user_id)===Number(u.id));return `<article class="card creator-record ${blocked?'restricted-record':''}"><div class="visit-head"><div><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><a class="link" href="https://www.instagram.com/${encodeURIComponent(u.instagram)}/" target="_blank" rel="noopener noreferrer">@${esc(u.instagram)} ↗</a></div><span class="badge ${blocked?'changes':u.approval_status==='approved'?'approved':'submitted'}">${blocked?T('Blacklisted','블랙리스트'):u.approval_status==='approved'?T('Approved','참여 승인'):u.approval_status==='rejected'?T('Not approved','참여 미승인'):T('Pending approval','승인 대기')}</span></div>${blocked&&events[0]?`<div class="notice"><strong>${esc(restrictionReason(events[0].reason))}</strong><p class="preline">${esc(events[0].note)}</p><small>${esc(events[0].actor_name)} · ${esc(events[0].created_at)}</small></div>`:''}<details><summary>${T('Participation approval','참여 승인 관리')}</summary><form data-api="approve_creator"><input type="hidden" name="id" value="${u.id}">${input('note',T('Message to influencer (required if rejected)','인플루언서 안내 메모 (미승인 시 필수)'),u.approval_note||'','text','maxlength="1000"')}<div class="form-error"></div><div class="button-row">${button(T('Approve participation','참여 승인'),'type="submit" name="status" value="approved"')}${button(T('Do not approve','미승인 처리'),'type="submit" name="status" value="rejected"','secondary')}</div>${blocked?`<p class="form-help">${T('Participation approval does not lift the blacklist restriction.','참여 승인만으로 블랙리스트가 해제되지는 않습니다.')}</p>`:''}</form></details><details><summary>${blocked?T('Lift blacklist restriction','블랙리스트 해제'):T('Add to blacklist','블랙리스트 등록')}</summary><form data-api="blacklist_creator"><input type="hidden" name="id" value="${u.id}"><input type="hidden" name="expected" value="${blocked?1:0}"><input type="hidden" name="decision" value="${blocked?'unblock':'block'}">${!blocked?`<label class="field">${T('Reason','등록 사유')}<select name="reason">${['no_show','late_cancel','content_issue','other'].map(r=>`<option value="${r}">${esc(restrictionReason(r))}</option>`).join('')}</select></label>`:''}<label class="field">${blocked?T('Reason for lifting restriction · operator only','해제 사유 · 운영자만 열람'):T('Incident details · operator only','상세 사유 · 운영자만 열람')}<textarea name="note" required maxlength="1500" placeholder="${T('Record the date, restaurant and what happened.','발생 날짜, 식당, 상황 등을 기록하세요.')}"></textarea></label><p class="form-help">${blocked?T('New bookings become available only if participation is also approved.','참여 승인된 계정만 신규 예약이 다시 가능해집니다.'):T('Blocks new bookings across all restaurants. Existing visits and payout records remain unchanged.','모든 식당의 신규 예약을 차단합니다. 기존 예약과 정산 기록은 유지됩니다.')}</p><div class="form-error"></div>${button(blocked?T('Lift restriction','블랙리스트 해제'):T('Block new bookings','블랙리스트 등록'),'type="submit"',blocked?'secondary':'primary')}</form></details>${events.length?`<details><summary>${T('Restriction history','등록·해제 이력')} (${events.length})</summary>${events.map(e=>`<div class="restriction-event"><strong>${e.action==='block'?T('Added','등록'):T('Removed','해제')} · ${esc(restrictionReason(e.reason))}</strong><p class="preline">${esc(e.note)}</p><small>${esc(e.actor_name||T('Operator','운영자'))} · ${esc(e.created_at)}</small></div>`).join('')}</details>`:''}</article>`}).join(''):`<div class="card empty"><p>${T('No matching influencers.','조건에 맞는 인플루언서가 없습니다.')}</p></div>`}
function creatorApprovals(){const all=state.creators||[],blocked=all.filter(u=>Number(u.is_blacklisted)).length;return `${title(T('INFLUENCER MANAGEMENT','인플루언서 관리'),view==='blacklist'?T('Blacklist','블랙리스트'):T('All influencers','전체 인플루언서'),T('Manage participation and booking restrictions across all restaurants. Incident notes are visible only to operators.','모든 식당의 인플루언서 참여와 예약 제한을 관리합니다. 상세 사유와 처리 이력은 운영자만 볼 수 있습니다.'))}<div class="stats"><div><span>${T('All influencers','전체 인플루언서')}</span><strong>${all.length}</strong></div><div><span>${T('Pending approval','승인 대기')}</span><strong>${all.filter(u=>u.approval_status==='pending').length}</strong></div><div><span>${T('Blacklisted','블랙리스트')}</span><strong>${blocked}</strong></div></div><div class="card creator-filters"><label class="field">${T('Search name, email or Instagram','이름·이메일·인스타그램 검색')}<input id="creator-search" type="search" value="${esc(creatorQuery)}"></label>${view!=='blacklist'?`<label class="field">${T('Status','상태')}<select id="creator-filter">${[['all',T('All','전체')],['pending',T('Pending','승인 대기')],['approved',T('Approved','참여 승인')],['blocked',T('Blacklisted','블랙리스트')]].map(([v,n])=>`<option value="${v}" ${creatorFilter===v?'selected':''}>${n}</option>`).join('')}</select></label>`:''}</div><div id="creator-list">${creatorList()}</div>`}
function title(kicker,title,sub=''){return `<div class="page-heading"><span class="eyebrow">${kicker}</span><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`}
function creatorHome(){const c=current();const bookings=state.bookings.filter(b=>Number(b.campaign_id)===Number(c.id));const b=bookings.find(b=>b.status!=='cancelled');const slots=state.slots.filter(s=>Number(s.campaign_id)===Number(c.id)&&Number(s.booked)<Number(s.capacity));return `${title(T('CREATOR HOME','인플루언서 홈'),field(c,'title'),T('A good meal is just the beginning.','맛있는 경험을 공유해 주세요.'))}${button(T('← All campaigns','← 전체 캠페인'),'data-view="home"','text-button')}${approvalNotice()}${picker()}${invite&&state.invite?`<form data-api="claim" class="notice"><input type="hidden" name="invite" value="${esc(invite)}"><p>${T('You have a new campaign invitation.','새 캠페인 초대가 도착했습니다.')}</p><div class="form-error"></div>${button(T('Accept invitation','초대 수락'),'type="submit"')}</form>`:''}<div class="creator-grid"><div><article class="campaign-cover"><div class="cover-top"><span class="pill">${T('DINING EXPERIENCE','다이닝 체험')}</span><span class="campaign-wordmark">${field(c,'title')}</span></div><div class="cover-bottom"><div><span>${T('RESTAURANT CAMPAIGN','식당 캠페인')}</span><h2>${field(c,'title')}</h2></div><span class="cover-number">CREATOR TABLE</span></div></article><div class="card location"><div><span class="eyebrow">${T('THE RESTAURANT','방문 매장')}</span><h3>${field(c,'branch')||T('Branch to be announced','방문 지점 준비 중')}</h3><p>${field(c,'address')||T('The restaurant is preparing its location and visiting hours.','식당에서 지점과 방문 일정을 준비하고 있습니다.')}</p></div><span class="location-icon">↗</span></div><div class="card"><h3>${T('What to share','참여 가이드')}</h3><p class="preline">${field(c,'guide')}</p>${hashtagPanel(c)}<p class="muted">${isProvided(c)?T('Show your QR before ordering, then submit your public Instagram post or Reel after the visit.','주문 전 QR을 제시하고, 방문 후 공개 인스타그램 게시물 또는 릴스 링크를 제출하세요.'):T('Keep your receipt. Submit a public Instagram post or Reel link after your visit.','영수증을 보관하고, 방문 후 공개된 인스타그램 게시물 또는 릴스 링크를 제출하세요.')}</p></div></div><div>${mealTerms(b||c)}${rewardCard(b||c)}<div class="card booking-card"><h3>${b?T('Your visit','내 방문 일정'):T('Pick your moment.','방문 시간을 선택하세요.')}</h3>${b?`<p class="date-text">${esc(b.starts_at.slice(0,16))} <small>KST</small></p>${badge(b.status)}<p class="muted">${T('Your reward terms were locked when you booked.','예약 당시의 지급 조건이 적용됩니다.')}</p>${button(T('View visit & submit content →','예약 확인 및 자료 제출 →'),'data-view="book"','primary full')}`:Number(state.user.is_blacklisted)?`<p class="notice">${T('New reservations are restricted. Contact the operator.','신규 예약이 제한되었습니다. 운영자에게 문의해 주세요.')}</p>`:state.user.approval_status!=='approved'?`<p class="notice">${T('Your registration is complete. Reservations will open for you after operator approval.','회원가입이 완료되었습니다. 운영자가 참여를 승인하면 예약할 수 있습니다.')}</p>`:!Number(c.active)||!slots.length?`<div class="empty small"><span>◷</span><p>${T('New visiting times are on their way.','방문 가능한 일정을 준비 중입니다.')}</p><small>${T('Please check back after the restaurant opens reservations.','식당에서 예약을 열면 이곳에서 선택할 수 있습니다.')}</small></div>`:`<form data-api="book"><label class="field">${T('Available date & time · Korea (KST)','방문 날짜·시간 · 한국 시간')}<select name="slot" required><option value="">${T('Choose a time','시간 선택')}</option>${slots.map(s=>`<option value="${s.id}">${esc(s.starts_at.slice(0,16))} · ${Number(s.capacity)-Number(s.booked)} ${T('left','명 가능')}</option>`).join('')}</select></label><label class="check"><input type="checkbox" required>${T('I have read the campaign requirements and reimbursement limit.','캠페인 작성 조건과 환급 한도를 확인했습니다.')}</label><div class="form-error"></div>${button(T('Reserve my visit →','방문 예약하기 →'),'type="submit"','primary full')}</form>`}</div><p class="aside-note">${T('All visit times are in Korea Standard Time (UTC+9).','모든 방문 시간은 한국 표준시(UTC+9) 기준입니다.')}</p></div></div>`}
function hashtagPanel(c){return c.required_tags?`<div class="notice"><strong>${T('Campaign hashtags','지정 해시태그')} · ${Number(c.enforce_tags)?T('Required','필수'):T('Recommended','안내')}</strong><p class="preline">${esc(c.required_tags)}</p>${button(T('Copy hashtags','해시태그 복사'),`type="button" data-tags="${esc(c.required_tags)}"`,'secondary')}<small>${T('Use these in the actual Instagram caption.','실제 인스타그램 게시물 캡션에 넣어 주세요.')}</small></div>`:''}
function submissionGuide(b){return `<section class="submission-guide"><h3>${T('Before you submit','게시물 제출 전 확인')}</h3><p class="preline">${field(b,'guide')}</p>${hashtagPanel(b)}<label class="field">${T('Caption published on Instagram','인스타그램에 게시한 캡션')}<textarea name="post_caption" required maxlength="10000" data-required-tags="${esc(b.required_tags||'')}" data-enforce="${Number(b.enforce_tags)}">${esc(b.post_caption||'')}</textarea></label><p class="tag-feedback" aria-live="polite"></p><label class="check"><input type="checkbox" name="guide_confirmed" value="1" required>${T('My actual post follows the guide and includes the required hashtags. The caption above matches my published post.','실제 게시물에 가이드와 필수 해시태그를 반영했으며, 위 캡션은 게시한 내용과 같습니다.')}</label><p class="form-help">${T('The app checks the caption you enter. The operator reviews the actual Instagram post separately.','입력한 캡션을 검사하며, 실제 인스타그램 게시물은 운영자가 별도로 확인합니다.')}</p></section>`}
function contentReview(b){return `<details class="submission-guide"><summary>${T('Content guide and submitted caption','게시물 가이드 및 제출 캡션')}</summary><p class="preline">${field(b,'guide')}</p>${hashtagPanel(b)}<strong>${T('Submitted caption','제출된 캡션')}</strong><p class="preline">${esc(b.post_caption||T('No caption saved for this earlier submission.','이전 제출 건으로 저장된 캡션이 없습니다.'))}</p></details>`}
function reservationQR(b){if(b.checked_in_at)return `<p class="notice"><strong>${T('Checked in','체크인 완료')}</strong> · ${esc(b.checked_in_at)}</p>`;if(b.status!=='reserved'||!b.checkin_url)return '';const qr=qrcode(0,'M');qr.addData(b.checkin_url);qr.make();return `<details class="reservation-qr" open><summary>${T('Reservation QR · show at the restaurant','예약 QR · 매장에서 보여 주세요')}</summary><div class="qr-code" role="img" aria-label="${T('Reservation check-in QR','예약 체크인 QR')}">${qr.createSvgTag({cellSize:4,margin:16,scalable:true})}</div><p>${isProvided(b)?T('Show this QR before ordering. The restaurant confirms your arrival and provides the campaign meal.','주문 전에 QR을 보여 주세요. 식당 담당자가 방문을 확인하고 캠페인 식사를 제공합니다.'):T('The restaurant scans this QR and confirms your arrival on the scheduled visit day.','예약된 방문 당일, 식당 담당자가 이 QR을 스캔하고 방문을 확인합니다.')}</p>${button(T('Copy check-in link','체크인 링크 복사'),`type="button" data-portal-copy="${esc(b.checkin_url)}"`,'secondary')}</details>`}
function checkinPage(){const b=qrBooking;return `${title(T('QR CHECK-IN','QR 방문 확인'),T('Confirm a creator’s arrival','인플루언서 방문 확인'),T('Scan the reservation QR with your phone camera and open its link, or paste the check-in link below.','휴대폰 기본 카메라로 예약 QR을 스캔해 링크를 여세요. 아래에 체크인 링크를 붙여 넣어도 됩니다.'))}<section class="card"><form data-api="checkin_preview">${input('token',T('Check-in link or QR code','체크인 링크 또는 QR 코드'),qrToken,'text','required maxlength="600" autocomplete="off"')}<div class="form-error">${esc(qrError)}</div>${button(T('Look up reservation','예약 확인'),'type="submit"')}</form></section>${b?`<section class="card"><span class="eyebrow">${T('Reservation','예약')} #${b.id}</span><h2>${esc(b.name)}</h2><p>@${esc(b.instagram)}</p><h3>${field(b,'title')}</h3><p>${field(b,'branch')}</p><p class="date-text">${esc(b.starts_at.slice(0,16))} · KST</p>${badge(b.status)}${mealTerms(b)}${mealTerms(b)}${b.checked_in_at?`<p class="notice"><strong>${T('Already checked in','체크인 완료')}</strong><br>${esc(b.checked_in_at)}</p>`:b.can_checkin?`<form data-api="checkin_confirm"><input type="hidden" name="token" value="${esc(qrToken)}"><label class="check"><input type="checkbox" required>${isProvided(b)?T('I verified this creator and confirm the menu or meal allowance will be provided once.','예약자를 확인했으며, 지정 메뉴 또는 한도 내 식사를 1회 제공하는 것을 확인합니다.'):T('I have confirmed that this creator arrived at our restaurant.','예약한 인플루언서가 매장에 도착한 것을 확인했습니다.')}</label><div class="form-error"></div>${button(isProvided(b)?T('Confirm meal provision','방문·식사 제공 확인'):T('Confirm check-in','체크인 완료 처리'),'type="submit"')}</form>`:`<p class="notice">${T('Check-in is available on the scheduled visit date (KST).','예약된 방문 당일(한국 시간)에 체크인할 수 있습니다.')}</p>`}</section>`:''}`}
function normalizedQR(value){const text=String(value).trim();if(/^[a-f0-9]{48}$/.test(text))return text;try{const url=new URL(text);if(url.origin===location.origin)return new URLSearchParams(url.hash.slice(1)).get('checkin')||''}catch(e){}return ''}
function creatorBookings(){return `${title(T('MY VISITS','나의 방문'),T('From first bite to reward.','예약부터 리워드까지.'),T('Follow your visit, content review and payout in one place.','방문 일정과 검수·지급 상태를 한곳에서 확인하세요.'))}${!state.bookings.length?`<div class="empty card"><span>◷</span><h3>${T('Your first visit is waiting.','첫 방문을 예약해 보세요.')}</h3>${button(T('Explore campaign','캠페인 보기'),'data-view="home"')}</div>`:state.bookings.map(b=>`<article class="card visit"><div class="visit-head"><div><span class="eyebrow">${field(b,'title')} · #${b.id}</span><h3>${field(b,'branch')||field(b,'title')}</h3><p>${esc(b.starts_at.slice(0,16))} · KST</p></div>${badge(b.status)}</div><div class="visit-numbers"><span>${isProvided(b)?T('Restaurant benefit','매장 제공 혜택'):T('Meal limit','식비 한도')}<strong>${isProvided(b)&&b.offer_type==='menu'?T('Set menu','지정 메뉴'):money(b.cap)}</strong></span><span>${T('Creator reward','추가 리워드')}<strong>${money(b.reward)}</strong></span><span>${T('Approved total','승인된 지급액')}<strong>${b.total===null?'—':money(b.total)}</strong></span></div>${mealTerms(b)}${reservationQR(b)}${b.review_note?`<div class="notice ${b.status==='changes'?'warn':''}">${T('Review note','검수 메모')}: ${esc(b.review_note)}</div>`:''}${['reserved','changes'].includes(b.status)?`<details ${b.status==='changes'?'open':''}><summary>${isProvided(b)?T('Submit Instagram post','인스타그램 게시물 제출'):T('Submit receipt & Instagram post','영수증과 인스타그램 게시물 제출')}</summary><form data-api="submit" enctype="multipart/form-data"><input type="hidden" name="id" value="${b.id}">${submissionGuide(b)}<div class="form-grid">${isProvided(b)?'':input('amount',T('Receipt total (KRW)','실제 결제 금액 (원)'),b.amount||'','number','min="1" max="10000000" required')}${input('post_url',T('Instagram post / Reel URL','인스타그램 게시물 / 릴스 링크'),b.post_url||'','url','required placeholder="https://www.instagram.com/p/..."')}</div>${isProvided(b)?'':`<label class="upload"><span>↑</span><strong>${T('Attach your receipt','영수증 첨부')}</strong><small>${T('JPG or PNG · up to 8 MB · hide unrelated personal information','JPG 또는 PNG · 최대 8MB · 불필요한 개인정보는 가려 주세요')}</small><input type="file" name="receipt" accept="image/jpeg,image/png" ${b.receipt_path?'':'required'}></label>`}${b.receipt_path?`<a class="link" target="_blank" rel="noopener" href="/inf/api.php?action=receipt&id=${b.id}&portal=${portal}">${T('View current receipt','기존 영수증 보기')}</a>`:''}<div class="form-error"></div>${button(T('Send for review','검수 요청'),'type="submit"')}<p class="form-help">${T('Submissions open after your scheduled visit time.','예약된 방문 시간 이후에 제출할 수 있습니다.')}</p></form></details>`:''}${b.post_url?`<a class="link" href="${esc(b.post_url)}" target="_blank" rel="noopener noreferrer">${T('View Instagram post ↗','인스타그램 게시물 보기 ↗')}</a>`:''}${b.status==='approved'?`<p class="notice">${T('Approved. Our team will coordinate payment with you through your invitation contact.','승인되었습니다. 운영사가 초대 연락 채널로 지급 절차를 안내합니다.')}</p>`:''}${b.status==='paid'?`<p class="muted">${T('Payment recorded','지급 처리 일시')}: ${esc(b.paid_at)} · ${T('Reference','거래 식별번호')}: ${esc(b.payment_ref)}</p>`:''}${b.status==='reserved'&&!b.checked_in_at?`<button class="text-button danger" data-cancel="${b.id}">${T('Cancel reservation','예약 취소')}</button>`:''}</article>`).join('')}`}
function managerHome(){const u=state.user,bs=state.bookings;const active=bs.filter(b=>b.status!=='cancelled');const review=bs.filter(b=>b.status==='submitted');const published=bs.filter(b=>b.post_url);return `${title(u.role==='admin'?T('OPERATIONS','운영사 관리'):T('RESTAURANT PORTAL','클라이언트 포털'),(u.role==='client'&&clientName()?esc(clientName())+' '+T('dashboard','대시보드'):T('A table full of possibilities.','우리 매장을 만나는 새로운 방법.')),u.role==='admin'?T('Manage partners, creators and every step of the campaign.','클라이언트부터 인플루언서 정산까지 관리하세요.'):T('Set your visiting hours and follow your restaurant’s creator visits.','방문 일정을 설정하고 우리 매장의 캠페인 진행을 확인하세요.'))}${state.user.role==='admin'?`<div class="notice approval-shortcut"><span>${T('Awaiting participation approval','참여 승인 대기')}: <strong>${(state.creators||[]).filter(u=>u.approval_status==='pending').length}</strong></span>${button(T('Review influencers →','인플루언서 확인 →'),'data-view="creators"','secondary')}</div>`:''}<div class="stats"><div><span>${T('Reservations','참여 예약')}</span><strong>${active.length}</strong><small>${T('Across your campaigns','관리 중인 캠페인 기준')}</small></div><div><span>${T('Awaiting review','검수 대기')}</span><strong>${review.length}</strong><small>${T('Handled by the operator','운영사에서 검수')}</small></div><div><span>${T('Posts submitted','게시물 제출')}</span><strong>${published.length}</strong><small>${T('Instagram posts & Reels','인스타그램 게시물 및 릴스')}</small></div></div><div class="manager-grid"><section class="card"><div class="section-head"><h3>${T('Visit schedule','방문 일정')}</h3><button class="text-button" data-view="book">${T('View all →','전체 보기 →')}</button></div>${!active.length?`<div class="empty small"><span>◷</span><p>${T('No reservations yet.','아직 예약이 없습니다.')}</p><small>${T('Add your branch and open visiting times first.','지점 정보와 예약 가능한 시간을 먼저 등록해 주세요.')}</small></div>`:active.slice().sort((a,b)=>a.starts_at.localeCompare(b.starts_at)).slice(0,8).map(b=>`<div class="schedule-row"><div class="date-tile"><strong>${esc(b.starts_at.slice(8,10))}</strong><span>${esc(b.starts_at.slice(5,7))}${T(' MONTH','월')}</span></div><div><strong>${esc(b.name)}</strong><p>${field(b,'branch')||field(b,'title')} · ${esc(b.starts_at.slice(11,16))} KST</p></div>${badge(b.status)}</div>`).join('')}</section><section class="dark-card"><span class="eyebrow">${T('MAKE ROOM FOR CREATORS','인플루언서 방문 준비')}</span><h2>${T('Your place.<br>Your schedule.','우리 매장,<br>우리 일정에 맞게.')}</h2><p>${T('Choose the branch, dates, weekdays and time slots that work for your team.','지점과 주소를 등록하고, 매장 운영에 맞는 요일·시간·예약 인원을 설정하세요.')}</p>${button(T('Manage campaign →','캠페인 설정 →'),'data-view="campaigns"','primary')}</section></div>`}
function managerBookings(){return `${title(T('VISITS & CONTENT','방문 및 콘텐츠'),T('Every visit, in view.','모든 방문을 한눈에.'),T('All times shown in Korea Standard Time (UTC+9).','모든 일정은 한국 표준시(UTC+9) 기준입니다.'))}<label class="filter field">${T('Status','진행 상태')}<select id="status-filter"><option value="">${T('All statuses','전체 상태')}</option>${Object.keys(label).map(s=>`<option value="${s}">${T(...label[s])}</option>`).join('')}</select></label><div id="booking-list">${renderManagerBookings('')}</div>`}
function renderManagerBookings(filter){const bs=state.bookings.filter(b=>!filter||b.status===filter);return !bs.length?`<div class="empty card"><h3>${T('No matching visits.','해당하는 방문 내역이 없습니다.')}</h3></div>`:bs.map(b=>`<article class="card visit"><div class="visit-head"><div><span class="eyebrow">#${b.id} · ${field(b,'title')}</span><h3>${esc(b.name)} <a class="ig" href="https://www.instagram.com/${encodeURIComponent(b.instagram)}/" target="_blank" rel="noopener noreferrer">@${esc(b.instagram)}</a></h3><p>${field(b,'branch')} · ${esc(b.starts_at.slice(0,16))} KST</p></div>${badge(b.status)}</div>${b.post_url?`<a class="link" href="${esc(b.post_url)}" target="_blank" rel="noopener noreferrer">${T('View submitted post ↗','제출 게시물 보기 ↗')}</a>`:''}${mealTerms(b)}${b.checked_in_at?`<p class="notice">${T('Checked in','체크인 완료')} · ${esc(b.checked_in_at)}</p>`:''}${state.user.role==='admin'?`${contentReview(b)}<div class="visit-numbers"><span>${T('Receipt amount','실제 결제액')}<strong>${b.amount?money(b.amount):'—'}</strong></span><span>${isProvided(b)?T('Reward after approval','승인 시 추가 리워드'):T('Refund + reward if approved','승인 시 환급 + 리워드')}<strong>${isProvided(b)?money(b.reward):b.amount?money(Math.min(Number(b.amount),Number(b.cap))+Number(b.reward)):'—'}</strong></span><span>${T('Contact email','연락 이메일')}<strong class="email">${esc(b.email)}</strong></span></div>${b.receipt_path?`<a class="link" href="/inf/api.php?action=receipt&id=${b.id}&portal=${portal}" target="_blank" rel="noopener">${T('Open receipt ↗','영수증 확인 ↗')}</a>`:''}${b.status==='submitted'?`<form data-api="review"><input type="hidden" name="id" value="${b.id}"><label class="check"><input type="checkbox" name="content_checked" value="1">${T('I opened the actual post and verified the guide and hashtags (required for approval).','실제 게시물을 열어 가이드·해시태그 반영을 확인했습니다. (승인 시 필수)')}</label><label class="field">${T('Review note · explain corrections to the creator','검수 메모 · 보완 요청 시 사유 필수')}<textarea name="note" maxlength="1500">${esc(b.review_note)}</textarea></label><div class="form-error"></div><div class="button-row">${button(T('Approve reimbursement','정산 승인'),'type="submit" name="decision" value="approve"')}${button(T('Request changes','보완 요청'),'type="submit" name="decision" value="changes"','secondary')}</div></form>`:''}${b.status==='approved'?`<form data-api="paid"><input type="hidden" name="id" value="${b.id}"><p class="notice">${T('Amount approved','승인 금액')}: <strong>${money(b.total)}</strong>. ${T('Transfer the money separately, then record the transaction here. This button does not send money.','별도로 실제 송금한 후 아래에 기록하세요. 이 버튼은 송금을 실행하지 않습니다.')}</p>${input('payment_ref',T('Transfer reference','송금 거래 식별번호'),'','text','required maxlength="180"')}<label class="check"><input type="checkbox" required>${T('I confirm that the transfer has been completed.','실제 송금을 완료했음을 확인합니다.')}</label><div class="form-error"></div>${button(T('Record completed payment','지급 완료 기록'),'type="submit"')}</form>`:''}${b.status==='paid'?`<p class="muted">${esc(b.payment_ref)} · ${esc(b.paid_at)}</p>`:''}`:''}</article>`).join('')}
function campaignSettings(){const c=current();const slots=state.slots.filter(s=>Number(s.campaign_id)===Number(c.id));return `${title(T('CAMPAIGN SETTINGS','캠페인 설정'),T('Set the table.','매장에 맞는 방문을 준비하세요.'),T('Location and schedules can be managed by the restaurant and the operator.','매장과 운영사 모두 지점 정보와 방문 일정을 관리할 수 있습니다.'))}${picker()}<div class="settings-grid"><section class="card"><h3>${T('Restaurant & campaign','매장 및 캠페인 정보')}</h3><form data-api="campaign"><input type="hidden" name="id" value="${c.id}"><label class="field">${T('Dining method','식사 이용 방식')}<select name="meal_mode"><option value="reimburse" ${!isProvided(c)?'selected':''}>${T('Pay first, then reimbursement','선결제·환급형')}</option><option value="provided" ${isProvided(c)?'selected':''}>${T('Restaurant provides meal after QR verification','QR 확인 후 식사 제공형')}</option></select></label><label class="field">${T('For QR meal provision','QR 식사 제공 방식')}<select name="offer_type"><option value="budget" ${c.offer_type!=='menu'?'selected':''}>${T('Within the meal allowance','지정 금액 한도 내 제공')}</option><option value="menu" ${c.offer_type==='menu'?'selected':''}>${T('Specified menu','지정 메뉴 제공')}</option></select></label>${input('menu_en',T('Provided menu · English','제공 메뉴 · 영문'),c.menu_en||'','text','maxlength="2000"')}${input('menu_ko',T('Provided menu · Korean','제공 메뉴 · 한글'),c.menu_ko||'','text','maxlength="2000"')}<p class="form-help">${T('QR meal provision pays only the extra reward after content approval. The meal itself is provided by the restaurant. New settings apply to new bookings only.','QR 식사 제공형은 식당에서 식사를 제공하고, 검수 후 추가 리워드만 지급합니다. 변경한 방식과 메뉴는 신규 예약부터 적용됩니다.')}</p><div class="form-grid">${input('title_en',T('Campaign title · English','캠페인 이름 · 영문'),c.title_en,'text','required maxlength="120"')}${input('title_ko',T('Campaign title · Korean','캠페인 이름 · 한글'),c.title_ko,'text','required maxlength="180"')}${input('branch_en',T('Branch · English','지점명 · 영문'),c.branch_en)}${input('branch_ko',T('Branch · Korean','지점명 · 한글'),c.branch_ko)}</div>${input('address_en',T('Address · English','주소 · 영문'),c.address_en)}${input('address_ko',T('Address · Korean','주소 · 한글'),c.address_ko)}<label class="field">${T('Content requirements · English','게시물 작성 조건 · 영문')}<textarea name="guide_en" maxlength="5000">${esc(c.guide_en)}</textarea></label><label class="field">${T('Content requirements · Korean','게시물 작성 조건 · 한글')}<textarea name="guide_ko" maxlength="5000">${esc(c.guide_ko)}</textarea></label><label class="field">${T('Campaign hashtags','지정 해시태그')}<textarea name="required_tags" maxlength="2000" placeholder="#LABAB #KoreanFood">${esc(c.required_tags||'')}</textarea></label><label class="check"><input type="checkbox" name="enforce_tags" value="1" ${Number(c.enforce_tags)?'checked':''}>${T('Block submission when required hashtags are missing','필수 해시태그 누락 시 제출 차단')}</label><p class="form-help">${T('Up to 30 tags separated by spaces. Uncheck for guidance only. Changes apply to new reservations; existing bookings keep their original guide and tags.','공백으로 구분해 최대 30개 입력하세요. 체크 해제 시 안내만 합니다. 변경 조건은 신규 예약부터 적용되며 기존 예약은 당시의 가이드·태그를 유지합니다.')}</p>${state.user.role==='admin'?`<div class="form-grid">${input('cap',T('Meal reimbursement / provision limit (KRW)','식비 환급 / 제공 한도 (원)'),c.cap,'number','required min="0" max="10000000"')}${input('reward',T('Additional reward (KRW)','추가 리워드 (원)'),c.reward,'number','required min="0" max="10000000"')}</div><p class="form-help">${T('New rates apply to future bookings. Existing bookings keep their original rates.','변경 금액은 신규 예약에만 적용되며 기존 예약 조건은 유지됩니다.')}</p>`:''}<label class="check"><input type="checkbox" name="active" value="1" ${Number(c.active)?'checked':''}>${T('Open this campaign for reservations','이 캠페인의 예약 접수 열기')}</label><p class="form-help">${T('Enter both addresses and add visiting times to accept reservations.','두 언어의 지점·주소와 방문 가능한 시간을 등록해야 예약을 받을 수 있습니다.')}</p><div class="form-error"></div>${button(T('Save campaign','캠페인 저장'),'type="submit"')}</form></section><section><div class="card"><h3>${T('Visiting hours','방문 가능 일정')}</h3><p class="muted">${T('Add recurring weekdays within a date range (up to 90 days). Times are KST.','최대 90일 범위에서 반복 요일을 선택하세요. 시간은 한국 시간 기준입니다.')}</p><form data-api="schedule"><input type="hidden" name="campaign_id" value="${c.id}"><div class="form-grid">${input('from',T('From','시작일'),'','date','required')}${input('to',T('Through','종료일'),'','date','required')}</div><fieldset class="weekdays"><legend>${T('Days of the week','방문 가능 요일')}</legend>${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekday" value="${d}"><span>${T(['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][d],['일','월','화','수','목','금','토'][d])}</span></label>`).join('')}</fieldset><div class="form-grid">${input('time',T('Visit time · KST','방문 시간 · 한국 시간'),'12:00','time','required')}${input('capacity',T('Creators per time','시간대별 예약 인원'),2,'number','required min="1" max="100"')}</div><div class="form-error"></div>${button(T('Add visiting times','예약 가능 일정 추가'),'type="submit"','primary full')}</form></div><div class="card"><h3>${T('Upcoming time slots','등록된 방문 일정')}</h3><div class="slot-list">${!slots.length?`<p class="muted">${T('No times added yet.','등록된 일정이 없습니다.')}</p>`:slots.map(s=>`<div class="slot-row"><div><strong>${esc(s.starts_at.slice(0,16))}</strong><small>${s.booked} / ${s.capacity} ${T('reserved','명 예약')}</small></div>${Number(s.booked)===0?`<button class="text-button danger" data-remove-slot="${s.id}" aria-label="${T('Remove time','일정 삭제')}">×</button>`:''}</div>`).join('')}</div></div></section></div>${state.user.role==='admin'?`<details class="card"><summary>${T('Add another restaurant client','새 식당 클라이언트 등록')}</summary><form data-api="new_campaign">${input('client_name',T('Restaurant / client name','식당 / 클라이언트 이름'),'','text','required maxlength="150"')}<div class="form-error"></div>${button(T('Create client campaign','클라이언트 캠페인 생성'),'type="submit"')}</form></details>`:''}`}
function invites(){return `${clientPages()}${title(T('INVITATIONS','초대 관리'),T('Bring people to the table.','초대로 연결되는 맛있는 경험.'),T('Generate a personal link, then send it in your DM. Each invitation works once and expires after 30 days.','개인 초대 링크를 만들어 DM으로 전달하세요. 초대는 1회 사용 가능하며 30일 후 만료됩니다.'))}<div class="settings-grid"><section class="card"><h3>${T('Create an invitation','초대 링크 만들기')}</h3><form data-api="invite"><label class="field">${T('Campaign','캠페인')}<select name="campaign_id">${options()}</select></label><label class="field">${T('Invite as','초대 역할')}<select name="role"><option value="influencer">${T('Influencer','인플루언서')}</option><option value="client">${T('Restaurant client','식당 클라이언트')}</option></select></label>${input('label',T('Name / internal note','대상 이름 / 관리 메모'),'','text','required maxlength="120"')}<p class="form-help">${T('Client accounts can see only their own restaurant’s campaigns and manage its location and hours.','클라이언트는 자기 식당의 캠페인만 보고 지점·일정을 관리할 수 있습니다.')}</p><div class="form-error"></div>${button(T('Generate invitation link','초대 링크 생성'),'type="submit"')}</form><div id="invite-result"></div></section><section class="card"><h3>${T('Recent invitations','최근 초대 내역')}</h3>${state.invites.length?state.invites.map(i=>`<div class="slot-row"><div><strong>${esc(i.label)}</strong><small>${i.role==='client'?T('Client','클라이언트'):T('Influencer','인플루언서')} · ${i.used_by?T('Accepted','가입 완료'):Number(i.expires_at)<Date.now()/1000?T('Expired / revoked','만료 / 취소'):T('Pending','수락 대기')}</small></div>${!i.used_by&&Number(i.expires_at)>Date.now()/1000?`<button class="text-button danger" data-revoke="${i.id}">${T('Revoke','취소')}</button>`:''}</div>`).join(''):`<p class="muted">${T('No invitations yet.','아직 생성된 초대가 없습니다.')}</p>`}</section></div>`}
function demoBanner(){return state?.demo?`<div class="demo-banner"><strong>${T('Demo workspace','체험용 화면')}</strong><span>${T('Sample data · no real payments','샘플 데이터 · 실제 지급 없음')}</span><nav><a href="/inf/admin/">${T('Operator','운영자')}</a><a href="/inf/client/">${T('Restaurant','클라이언트')}</a><a href="/inf/">${T('Influencer','인플루언서')}</a></nav></div>`:''}
function render(){syncRoleLanguage();document.documentElement.lang=lang;applyRoleTheme();if(!state){return}if(!state.user){$('#app').innerHTML=header()+(setup||state.invite?.role==='client'||['admin','client'].includes(portal)?portalGuest():guest())+footer();return}const manager=state.user.role!=='influencer';const tabs=manager?[['home',T('Overview','대시보드')],['book',T('Visits & content','방문 및 콘텐츠')],['checkin',T('QR check-in','QR 방문 확인')],['campaigns',T('Branch & schedule','지점 및 일정')],...(state.user.role==='admin'?[['clients',T('Clients','클라이언트 관리')],['creators',T('All influencers','전체 인플루언서')],['blacklist',T('Blacklist','블랙리스트')],['invites',T('Invitations','초대 관리')]]:[])]:[['home',T('Campaigns','캠페인 목록')],['book',T('My visits & rewards','내 방문 및 리워드')]];if(!tabs.some(t=>t[0]===view)&&!(state.user.role==='influencer'&&view==='detail'))view='home';const body=manager?(view==='home'?managerHome():view==='book'?managerBookings():view==='checkin'?checkinPage():view==='campaigns'?campaignSettings():view==='clients'?clientManagement():['creators','blacklist'].includes(view)?creatorApprovals():invites()):(view==='home'?catalogHome():view==='detail'?creatorHome():creatorBookings());$('#app').innerHTML=header()+demoBanner()+`<div class="workspace"><aside class="sidebar"><span class="eyebrow">${state.user.role==='admin'?T('OPERATOR','운영사'):state.user.role==='client'?T('RESTAURANT','식당 클라이언트'):T('CREATOR','인플루언서')}</span><nav>${tabs.map(([v,n])=>`<button data-view="${v}" class="${view===v?'active':''}"><span>${icons[v]}</span>${n}</button>`).join('')}</nav><div class="sidebar-bottom"><span class="small-mark">L</span><p>${T('Good food brings<br>people together.','맛있는 경험이<br>우리를 연결합니다.')}</p><small>LABAB CREATOR TABLE</small></div></aside><main class="main-content">${body}</main></div>`+footer()}
function portalGuest(){const isAdmin=!!setup||new URLSearchParams(location.search).get('view')==='admin';const reg=authMode==='register'&&(setup||state.invite);return `<main class="guest portal-guest"><section class="intro"><span class="eyebrow orange">${isAdmin?T('OPERATOR PORTAL','운영사 포털'):T('RESTAURANT PARTNERS','식당 클라이언트')}</span><h1>${isAdmin?T('Every creator.<br>Every detail.','초대부터 정산까지,<br>한곳에서.'):(clientName()?esc(clientName())+'<br>'+T('Partner portal','전용 관리 페이지'):T('Your table.<br>Their stories.','우리 매장에서,<br>새로운 이야기가.'))}</h1><p class="lede">${isAdmin?T('Coordinate invitations, campaigns, content reviews and creator rewards.','초대·캠페인·게시물 검수·리워드 지급을 관리하세요.'):T('Welcome creators to your restaurant. Set your location and visiting hours, then follow every visit.','우리 매장을 방문할 인플루언서를 맞이하세요. 지점과 방문 시간을 설정하고 진행 상황을 확인할 수 있습니다.')}</p><div class="portal-features"><div><b>01</b><span>${T('Branch & visiting hours','지점 및 방문 일정')}<small>${T('Your address, weekdays and reservation capacity','주소·요일·시간·예약 가능 인원 설정')}</small></span></div><div><b>02</b><span>${T('Reservations & content','예약 및 콘텐츠')}<small>${T('Creator schedules and submitted Instagram posts','방문 일정과 제출된 인스타그램 게시물 확인')}</small></span></div><div><b>03</b><span>${isAdmin?T('Review & payout','검수 및 지급'):T('Your restaurant, privately','우리 매장의 정보만')}<small>${isAdmin?T('Approve evidence and record completed transfers','증빙 승인 및 실제 송금 내역 기록'):T('Access is limited to your own campaigns','담당 식당의 캠페인에만 접근 가능')}</small></span></div></div></section><section class="auth-panel"><div class="mini-logo">${isAdmin?T('OPERATOR ACCESS','운영사 전용'):T('CLIENT ACCESS','클라이언트 전용')}</div><h2>${reg?T('Create your account.','계정을 만들어 주세요.'):T('Welcome back.','다시 만나 반가워요.')}</h2><p>${reg?T('Use your own email and password.','사용할 이메일과 비밀번호를 설정하세요.'):T('Sign in with your invited account.','초대받은 계정으로 로그인하세요.')}</p><form data-api="${reg?'register':'login'}"><input type="hidden" name="invite" value="${esc(invite)}"><input type="hidden" name="setup" value="${esc(setup)}">${reg?input('name',T('Name','이름'),'','text','required autocomplete="name" maxlength="100"'):''}${input('email',reg?T('Email address','이메일'):T('Email or username','이메일 또는 아이디'),'',reg?'email':'text','required autocomplete="username" maxlength="180"')}${input('password',T('Password','비밀번호'),'','password',`required autocomplete="${reg?'new-password':'current-password'}" ${reg?'minlength="12"':''} maxlength="128"`)}${reg?`<p class="form-help">${T('Use a password of at least 12 characters.','12자 이상의 비밀번호를 사용하세요.')}</p>`:''}<div class="form-error"></div>${button(reg?T('Create account →','계정 만들기 →'):T('Sign in →','로그인 →'),'type="submit"','primary full')}</form>${reg?`<button class="auth-switch" data-mode="login">${T('Already registered? Sign in','이미 가입했나요? 로그인')}</button>`:''}<p class="invitation-note">${T('Your role is set by your invitation. Contact the operator if you need access to another restaurant.','초대에 따라 접근 권한이 부여됩니다. 다른 매장에 대한 권한이 필요하면 운영사에 문의해 주세요.')}</p></section></main>`}
function footer(){return `<footer>© ${new Date().getFullYear()} LABAB Creator Table <span>${T('Taste. Share. Earn.','맛보고, 공유하고, 리워드 받기.')}</span></footer>`}
document.addEventListener('click',async e=>{const el=e.target.closest('button');if(!el)return;if(el.dataset.manageCampaign){selectedCampaign=el.dataset.manageCampaign;view='campaigns';render();return}if(el.dataset.clientInvite){selectedCampaign=el.dataset.clientInvite;view='invites';render();document.querySelector('select[name=role]').value='client';return}if(el.dataset.portalCopy){try{await navigator.clipboard.writeText(el.dataset.portalCopy);toast(T('URL copied.','주소를 복사했습니다.'))}catch(e){toast(T('Select and copy the URL.','주소를 선택해 복사해 주세요.'))}return}if(el.dataset.tags){try{await navigator.clipboard.writeText(el.dataset.tags);toast(T('Hashtags copied.','해시태그를 복사했습니다.'))}catch(e){toast(T('Select and copy the tags shown above.','표시된 해시태그를 선택해 복사해 주세요.'))}return}if(el.dataset.lang){if(busy)return;const drafts=[...document.querySelectorAll('form[data-api]')].map(f=>({action:f.dataset.api,id:f.querySelector('[name=id]')?.value||'',values:[...f.elements].filter(x=>x.name).map(x=>({name:x.name,value:x.value,checked:x.checked,type:x.type,files:x.type==='file'?[...x.files]:null}))}));lang=el.dataset.lang;try{localStorage.setItem('labab-language-'+screenRole(),lang)}catch(e){}render();for(const d of drafts){const form=[...document.querySelectorAll('form[data-api]')].find(f=>f.dataset.api===d.action&&(f.querySelector('[name=id]')?.value||'')===d.id);if(!form)continue;for(const v of d.values){const elements=[...form.elements].filter(x=>x.name===v.name);const el=elements.find(x=>x.type==='checkbox'?x.value===v.value:true);if(!el)continue;if(v.type==='file'){if(v.files?.length){const dt=new DataTransfer();v.files.forEach(f=>dt.items.add(f));el.files=dt.files}}else if(v.type==='checkbox'){el.checked=v.checked}else{el.value=v.value}}}return}if(el.dataset.campaign){selectedCampaign=el.dataset.campaign;view='detail';render();return}if(el.dataset.view){view=el.dataset.view;render();window.scrollTo(0,0);return}if(el.dataset.mode){authMode=el.dataset.mode;render();return}if(el.dataset.copy){try{await navigator.clipboard.writeText($('#invitation-url').value);toast(T('Link copied.','링크를 복사했습니다.'))}catch(e){$('#invitation-url').select();toast(T('Select and copy the link.','선택된 링크를 복사해 주세요.'))}return}let action='',data={};if(el.dataset.action==='logout')action='logout';if(el.dataset.cancel){if(!confirm(T('Cancel this reservation?','예약을 취소할까요?')))return;action='cancel';data.id=el.dataset.cancel}if(el.dataset.removeSlot){if(!confirm(T('Remove this visiting time?','방문 가능 일정을 삭제할까요?')))return;action='remove_slot';data.id=el.dataset.removeSlot}if(el.dataset.revoke){if(!confirm(T('Revoke this invitation?','초대를 취소할까요?')))return;action='revoke_invite';data.id=el.dataset.revoke}if(action){el.disabled=true;try{await api(action,data);await refresh()}catch(e){toast(T(...(err[e.message]||err.server_error)));el.disabled=false}}});
document.addEventListener('change',e=>{if(e.target.id==='campaign-picker'){selectedCampaign=e.target.value;render()}if(e.target.id==='status-filter')$('#booking-list').innerHTML=renderManagerBookings(e.target.value)});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.api)return;e.preventDefault();if(busy)return;const data=new FormData(f);const action=f.dataset.api;if(action==='checkin_preview'){qrToken=normalizedQR(data.get('token'));data.set('token',qrToken)}if(e.submitter?.name)data.set(e.submitter.name,e.submitter.value);if(action==='schedule')data.set('days',data.getAll('weekday').join(','));const error=f.querySelector('.form-error');error.textContent='';busy=true;const buttons=[...f.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const result=await api(action,data);if(action==='checkin_preview'||action==='checkin_confirm'){qrBooking=result.booking;qrError='';view='checkin';render();return}if(action==='invite'){await refresh();$('#invite-result').innerHTML=`<div class="notice"><strong>${T('Your invitation is ready.','초대 링크가 생성됐습니다.')}</strong><p>${T('Copy this link now. For security, it is only shown once.','지금 링크를 복사하세요. 보안을 위해 링크는 한 번만 표시됩니다.')}</p><input id="invitation-url" readonly value="${esc(result.url)}" aria-label="${T('Invitation URL','초대 링크')}">${button(T('Copy link','링크 복사'),'type="button" data-copy="1"','secondary')}</div>`;return}if(['register','claim'].includes(action)){invite='';setup='';history.replaceState({},'',location.pathname+location.search)}if(action==='book')view='book';if(action==='register')view='home';if(action==='new_campaign'){selectedCampaign=result.id;view='campaigns';}await refresh();toast(action==='schedule'?T(`${result.count} visiting times added.`,`${result.count}개 일정을 추가했습니다.`):T('Saved successfully.','저장했습니다.'))}catch(e){error.textContent=T(...(err[e.message]||err.server_error));buttons.forEach(b=>b.disabled=false)}finally{busy=false}});
syncRoleLanguage();applyRoleTheme();
refresh().catch(e=>{$('#app').innerHTML=header()+`<main class="empty"><h2>${T('Unable to load the campaign','캠페인을 불러오지 못했습니다.')}</h2><p>${T(...(err[e.message]||err.server_error))}</p><a class="primary" href="/inf/">${T('Try again','다시 시도')}</a></main>`});

document.addEventListener('input',e=>{if(e.target.id==='creator-search'){creatorQuery=e.target.value;$('#creator-list').innerHTML=creatorList()}});
document.addEventListener('change',e=>{if(e.target.id==='creator-filter'){creatorFilter=e.target.value;$('#creator-list').innerHTML=creatorList()}});

document.addEventListener('input',e=>{if(e.target.name!=='post_caption')return;const el=e.target,tags=(el.dataset.requiredTags||'').split(/\s+/).filter(Boolean),found=(el.value.match(/(?<![\p{L}\p{N}_])#[\p{L}\p{N}_]+/gu)||[]).map(x=>x.toLowerCase()),missing=tags.filter(x=>!found.includes(x.toLowerCase()));const msg=missing.length?T('Missing: ','누락: ')+missing.join(' '):T('All specified hashtags are included.','지정 해시태그가 모두 포함되어 있습니다.');el.closest('form').querySelector('.tag-feedback').textContent=tags.length?msg:'';el.setCustomValidity(missing.length&&el.dataset.enforce==='1'?msg:'')});

document.addEventListener('input',e=>{if(e.target.id==='client-search'){clientQuery=e.target.value;$('#client-list').innerHTML=clientRows()}});

window.addEventListener('hashchange',()=>{const next=new URLSearchParams(location.hash.slice(1)).get('checkin');if(next){qrToken=next;qrBooking=null;view='checkin';refresh().catch(()=>toast(T('Unable to load reservation.','예약을 불러오지 못했습니다.')))}});
